BRANCH_TOOLS=[
 {"name":"athena_branch_observe","description":"Record one witnessed calibrated branch reward observation and apply EWMA hibernation/resurrection policy.","inputSchema":{"type":"object","required":["branch_id","basis_id","reward","witness"],"properties":{"branch_id":{"type":"string"},"basis_id":{"type":"string"},"reward":{"type":"number"},"witness":{"type":"object","required":["verified","ref"],"properties":{"verified":{"type":"boolean"},"ref":{"type":"string"}},"additionalProperties":True},"policy":{"type":"object"},"triggers":{"type":"array","items":{"type":"object"}},"metadata":{"type":"object"},"actor":{"type":"string"}},"additionalProperties":False}},
 {"name":"athena_branch_state","description":"Read branch lifecycle state for one branch, optionally on one metric basis.","inputSchema":{"type":"object","required":["branch_id"],"properties":{"branch_id":{"type":"string"},"basis_id":{"type":["string","null"]}},"additionalProperties":False}},
 {"name":"athena_branch_list","description":"List branch lifecycle states, optionally filtered by ACTIVE/HIBERNATED/REVIEW.","inputSchema":{"type":"object","properties":{"status":{"type":["string","null"]},"limit":{"type":"integer","minimum":1,"maximum":500}},"additionalProperties":False}},
 {"name":"athena_branch_review","description":"Move a hibernated branch into REVIEW only from a verified new_evidence/new_gap/bridge_demand trigger.","inputSchema":{"type":"object","required":["branch_id","basis_id","trigger"],"properties":{"branch_id":{"type":"string"},"basis_id":{"type":"string"},"trigger":{"type":"object","required":["type","ref"],"properties":{"type":{"type":"string","enum":["new_evidence","new_gap","bridge_demand"]},"ref":{"type":"string"}},"additionalProperties":False},"actor":{"type":"string"}},"additionalProperties":False}},
]
BRANCH_TOOL_NAMES={tool['name'] for tool in BRANCH_TOOLS}
BRANCH_RESOURCE={"uri":"athena://branches","name":"AOR Branch Lifecycle Ledger","mimeType":"application/json"}
